from dsl import *

modul("B", "HBOD verstehen", "Firma, Abläufe, Onboarding, Lager, Marketing und die wichtigsten Marktplätze")

stapel("t06", "B", "HBOD auf einen Blick",
    "Was HBOD ist, wie HBOD Geld verdient und wie du es in einem Satz erklärst.", [
    Z("t06-01", "In welchem Jahr wurde HBOD gegründet (laut Company Profile)?", 2016.0,
      "Die Unternehmenspräsentation nennt 2016 und „10+ years of marketplace expertise“.", einheit="", dez=0, quelle="Unternehmenspräsentation 2026"),
    S("t06-02", "Wo sitzt HBOD und wie groß ist das Fulfillment-Center?",
      ["Mülheim an der Ruhr, rund 20.000 m²", "Duisburg, rund 5.000 m²", "Düsseldorf, rund 50.000 m²", "Essen, rund 2.000 m²"],
      "Alle Kanäle werden aus diesem einen Lager bedient.", quelle="Unternehmenspräsentation 2026"),
    S("t06-03", "Wie viele Marktplätze und Länder nennt das Company Profile?",
      ["Über 40 Marktplätze in über 30 Ländern", "5 Marktplätze in Deutschland", "Über 200 Marktplätze weltweit", "10 Marktplätze in 3 Ländern"],
      "In anderen Unterlagen stehen auch 50 oder 70 Plattformen. Für Kundengespräche den aktuellen Stand intern bestätigen lassen.", quelle="Unternehmenspräsentation 2026", hinweis="Zahl schwankt in den Unterlagen"),
    S("t06-04", "Worauf ist HBOD besonders spezialisiert?",
      ["Mode und vor allem Wäsche/Unterwäsche", "Elektronik", "Möbel", "Lebensmittel"],
      "Der Schwerpunkt liegt auf Textilien und Unterwäsche. Dazu kommen weitere kompakte Produkte.", quelle="Unternehmenspräsentation 2026"),
    M("t06-05", "Was zahlt eine Marke bei HBOD nicht? Kreuze alles Richtige an.",
      ["Onboarding-Gebühr", "Integrationsgebühr", "Monatliche Grund- oder Lizenzgebühr"],
      ["Provision auf verkaufte Artikel", "Logistikkosten nach Preisliste"],
      "HBOD arbeitet rein erfolgsbasiert: Provision und Logistik ja, Fixkosten nein.", quelle="Unternehmenspräsentation 2026"),
    S("t06-06", "Wie verdient HBOD sein Geld?",
      ["Über eine Provision auf den Umsatz nach Retouren. Die Logistik wird nach Preisliste berechnet.", "Über eine feste Monatsgebühr", "Über den Einkauf und Weiterverkauf der Ware mit Aufschlag", "Über Werbeeinnahmen der Marktplätze"],
      "HBOD arbeitet rein erfolgsbasiert und verdient nur, wenn über die Zusammenarbeit Umsatz entsteht. Die Marktplatzprovisionen gibt HBOD 1:1 weiter.", quelle="Unternehmenspräsentation 2026"),
    S("t06-07", "Wie ist die HBOD-Provision gestaffelt?",
      ["12 % bis 100.000 € Monatsumsatz, 10 % ab 100.000 € (nur für diesen Monat)", "Immer 15 %", "5 % im ersten Jahr, danach 20 %", "Je nach Verhandlung zwischen 1 und 30 %"],
      "Laut Kollege ist die Staffel fix und nicht verhandelbar. Die frühere 15-%-Stufe wurde gestrichen.", quelle="Einweisung Produktkalkulation"),
    W("t06-08", "Die Logistik ist bei HBOD ein eigenes Profit-Center, an dem HBOD gut verdient.", False,
      "Falsch. Laut Company Profile läuft die Logistik \"at cost\" zu sehr wettbewerbsfähigen Preisen, sie ist kein eigenes Profit-Center. In Kundenmails sagst du das aber nicht als \"zu unseren Kosten\", sondern: sehr gute DHL-Konditionen durch unser Volumen.", quelle="Unternehmenspräsentation 2026, Deine Mail-Regeln"),
    S("t06-09", "Wie beschreibt der Kollege HBOD in einem Satz?",
      ["\"Mit einem Vertrag auf über 40 Marktplätzen verkaufen – alles aus einer Hand.\"", "\"Wir sind ein Paketdienst für Marken.\"", "\"Wir kaufen Ihre Ware zum besten Preis.\"", "\"Wir sind ein Marktplatz wie Amazon.\""],
      "Danach kommen fast immer Rückfragen: Kauft ihr die Ware? Versendet ihr nur? Darauf solltest du vorbereitet sein.", quelle="Einarbeitung"),
    S("t06-10", "Was heißt \"erfolgsbasiert\" aus Sicht der Marke?",
      ["HBOD verdient nur, wenn Endkunden kaufen und die Ware behalten", "Die Marke zahlt nur, wenn sie zufrieden ist", "HBOD bekommt einen Bonus am Jahresende", "Die Marke zahlt eine Gebühr pro Marktplatz"],
      "Die Provision fällt auf den Umsatz nach Retouren an. Bei Retouren wird sie zurückgebucht.", quelle="Unternehmenspräsentation 2026"),
    P("t06-11", "Ordne die Personen ihrer Rolle zu (laut Company Profile).",
      [["Dirk Bachmann", "CEO"], ["Timo Hage", "COO"], ["Martin Muhr", "CFO"], ["Laurin Knoke", "Key Account Manager"]],
      "Ob die Rollen im Profil noch aktuell sind, kannst du im Team kurz prüfen.", quelle="Unternehmenspräsentation 2026"),
    S("t06-12", "Was bedeutet \"asset-light\" bei HBOD?",
      ["HBOD kauft die Ware nicht ein und bindet kein eigenes Kapital in Ware", "HBOD hat kein Lager", "HBOD arbeitet ohne Computer", "HBOD verkauft nur leichte Artikel"],
      "Die Ware gehört bis zum Verkauf der Marke. HBOD wächst über die Dienstleistung, nicht über eigenen Warenbestand.", quelle="Unternehmenspräsentation 2026"),
],
    punkte=["Gegründet 2016, Sitz und Fulfillment-Center (rund 20.000 m²) in Mülheim an der Ruhr. Über 40 Marktplätze in über 30 Ländern.", "Schwerpunkt: Mode und vor allem Wäsche.", "Rein erfolgsbasiert: keine Onboarding-, Integrations- oder Monatsgebühr. HBOD verdient eine Provision auf den Umsatz nach Retouren, die Logistik läuft nach Preisliste.", "HBOD-Provision: 12 % bis 100.000 € Monatsumsatz, 10 % darüber. In Mails: „10 bis 12 % je nach Umsatz“. Die Marktplatzprovisionen gibt HBOD 1:1 weiter.", "Asset-light: HBOD kauft die Ware nicht ein, sie bleibt bis zum Verkauf Eigentum der Marke."],
    merksatz="Mit einem Vertrag auf über 40 Marktplätzen verkaufen, alles aus einer Hand.",
    quelle="Unternehmenspräsentation 2026, Einweisung Produktkalkulation, Deine Mail-Regeln")

stapel("t07", "B", "Abteilungen und Ablauf",
    "Wer bei HBOD was macht und wie eine Marke vom Vertrag bis zur Auszahlung läuft.", [
    R("t07-01", "Bringe den Ablauf vom Vertrag bis zur Auszahlung in die richtige Reihenfolge.",
      ["Vertrag abschließen", "Marke schickt Stammdaten und Bilder", "Marktplatzmanagement legt die Artikel im System an", "HBOD bestellt die Ware (Bestellvorschlag)", "Wareneingang im Lager", "Artikel gehen auf den Marktplätzen live", "Verkauf, Versand und ggf. Aktionen", "Monatsabrechnung und Auszahlung"],
      "Wichtig: HBOD bestellt erst, wenn die Artikel im System angelegt sind.", quelle="Deine Zusammenfassung, Unternehmenspräsentation 2026"),
    P("t07-02", "Ordne jeder Abteilung ihre Hauptaufgabe zu.",
      [["Marktplatzmanagement (früher Onboarding)", "Artikel anlegen und auf die Plattformen bringen"], ["Marketing", "Sale-Events, Preisreduktionen und Werbekampagnen"], ["Account Health", "SLAs überwachen und Sperren lösen"], ["Abrechnungen / Bestellungen", "Monatsabrechnungen, Gutschriften und Bestellungen"], ["Kundenservice", "Anfragen der Endkunden beantworten"]],
      "Der Begriff \"Onboarding\" für das Marktplatzmanagement gilt intern als veraltet.", quelle="Deine Zusammenfassung"),
    S("t07-03", "Was macht die Marketingabteilung bei HBOD nicht?",
      ["Klassische Außenwerbung wie Plakate oder TV-Spots für die Marke", "Teilnahme an Sale-Events", "Preisreduktionen", "Werbekampagnen auf Marktplätzen"],
      "Der Name ist etwas irreführend: Marketing bei HBOD heißt Aktionen, Preise und Marktplatzwerbung.", quelle="Deine Zusammenfassung"),
    R("t07-04", "Bringe den Ablauf im Lager in die richtige Reihenfolge.",
      ["Wareneingang (Ware kommt palettenweise an)", "Einlagern", "Kommissionierung (Artikel picken)", "Verpacken und an den Paketdienst übergeben", "Bei Rücksendung: Retourenabteilung"],
      "Kommissionierung heißt: Artikel für eine Bestellung aus dem Regal holen.", quelle="Deine Zusammenfassung"),
    M("t07-05", "Was kann mit einem retournierten Artikel passieren? Kreuze alles Richtige an.",
      ["Er wird direkt wieder zum Verkauf freigegeben", "Er wird aufbereitet und dann wieder verkauft", "Er wird gespendet, verschrottet oder an die Marke zurückgeschickt"],
      ["Er wird immer vernichtet", "Er wird automatisch billiger auf eBay verkauft"],
      "HBOD versucht, jeden Artikel wieder verkaufsfähig zu machen. Nur defekte Ware wird aussortiert.", quelle="Deine Zusammenfassung"),
    S("t07-07", "Ein Kunde fragt dich nach steuerlichen Details der Abrechnung. Wen fragst du intern?",
      ["Die Buchhaltung bzw. Accounting & Finance", "Das Lager", "Den Kundenservice für Endkunden", "Niemanden, du schätzt es einfach"],
      "Bei Steuern, Haftung und Recht gilt: nicht raten, sondern intern klären und dann antworten.", quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    S("t07-08", "Was ist die Peak Season?",
      ["Die umsatzstärkste Zeit von Black Friday bis Weihnachten mit viel mehr Arbeit", "Die Sommerpause", "Die Zeit der Inventur", "Die ersten Wochen eines neuen Kunden"],
      "In der Peak Season gibt es Samstagsschichten. Der Wareneingang kann von etwa 7 auf 14 Tage steigen.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t07-09", "Warum ist Account Health so wichtig?",
      ["Bei SLA-Verstößen drohen Sperren oder der Verlust von Prime, und das trifft alle Marken bei HBOD", "Weil sonst die Mitarbeiter krank werden", "Weil die Marke sonst keine Rechnung bekommt", "Weil das die Provision erhöht"],
      "Alle Marken laufen über HBODs Verkäuferkonten. Kommen Pakete zu spät oder gibt es zu viele Stornos, kann ein Marktplatz Prime entziehen oder das Konto sperren, und das trifft dann alle Marken.", quelle="Einarbeitung"),
    W("t07-10", "Probleme bei einer einzelnen Marke, zum Beispiel viele Stornos, können auch andere HBOD-Marken treffen.", True,
      "Richtig. Alle Marken laufen über HBODs Verkäuferkonten. Deshalb achtet HBOD so streng auf Lagerbestand und SLAs.", quelle="Einarbeitung"),
],
    punkte=["Ablauf: Vertrag, Stammdaten und Bilder, Artikel im System anlegen, Bestellvorschlag, Wareneingang, live, Verkauf, Monatsabrechnung und Auszahlung.", "Abteilungen: Marktplatzmanagement legt Artikel an, Marketing macht Aktionen und Werbung, Account Health überwacht die SLAs, die Abrechnung erstellt Gutschriften, der Kundenservice beantwortet Endkunden.", "Im Lager: Wareneingang, Einlagern, Kommissionierung (Picken), Verpacken und Übergabe an den Paketdienst, bei Rücksendungen die Retourenabteilung.", "Alle Marken laufen über HBODs Verkäuferkonten. Probleme einer Marke, etwa viele Stornos, können deshalb alle treffen.", "Peak Season von Black Friday bis Weihnachten: viel mehr Arbeit, der Wareneingang kann von etwa 7 auf 14 Tage steigen."],
    merksatz="Erst die Daten, dann die Ware.",
    quelle="Deine Zusammenfassung, Unternehmenspräsentation 2026, Einarbeitung")

stapel("t08", "B", "Onboarding neuer Marken",
    "Was eine Marke liefern muss, wie die Erstbestellung läuft und was den Start verzögert.", [
    M("t08-01", "Welche Unterlagen bekommt ein neuer Kunde mit dem Vertrag? Kreuze alles Richtige an.",
      ["Anlieferbedingungen", "Stammdatenblatt zum Ausfüllen", "Vorgaben für Produktfotos", "Preisliste von HBOD", "GPSR-Formular (Produktsicherheit)", "Brand Info (Marken-Steckbrief)"],
      ["Rechnung für die Onboarding-Gebühr", "Zugangsdaten zu HBODs Marktplatzkonten"],
      "Eine Onboarding-Gebühr gibt es nicht. Zugangsdaten zu HBOD-Konten bekommt die Marke nie.", quelle="Deine Zusammenfassung"),
    Z("t08-02", "Wie viele Stück je SKU umfasst die Initialorder mindestens?", 3.0,
      "Mindestens 3 Stück je SKU, oft 5, 8 oder 10 je nach Größe und Farbe. Für Bundles eher mehr.", einheit="Stück", dez=0, quelle="Unternehmenspräsentation 2026"),
    S("t08-03", "Für welchen Zeitraum plant HBOD den Erstbestand?",
      ["Für etwa 8 Wochen Absatz, danach rollierend 4 bis 6 Wochen Reichweite", "Für ein ganzes Jahr", "Für eine Woche", "Das entscheidet immer DHL"],
      "HBOD will kein großes Lager aufbauen, aber auch nicht leerlaufen (Lost Sales).", quelle="Unternehmenspräsentation 2026, Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t08-04", "Wann verschickt HBOD Bestellvorschläge?",
      ["Jeden Mittwoch. Die Marke darf mehr oder weniger liefern.", "Einmal im Quartal", "Nur, wenn die Marke anruft", "Täglich um 17 Uhr"],
      "Der Bestellvorschlag ist ein Vorschlag. Bestätigte Mengen muss die Marke dann einhalten.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Wochentag stammt aus einer Gesprächsaufnahme. Intern bestätigen."),
    S("t08-05", "Wie schnell gehen Artikel in der Regel live?",
      ["Meist 1 bis 4 Wochen nach vollständigen Stammdaten, online sobald der Bestand gebucht ist", "Am selben Tag", "Frühestens nach 6 Monaten", "Erst nach der nächsten Townhall"],
      "Voraussetzung: Daten und Bilder sind vollständig.", quelle="Unternehmenspräsentation 2026"),
    S("t08-06", "Was verzögert den Start am häufigsten?",
      ["Fehlende oder späte Stammdaten und Bilder", "Zu viele Mitarbeiter im Lager", "Zu niedrige Preise", "Zu gutes Wetter"],
      "Das sollte man Kunden vorab klar sagen. Bei Saisonware früh den Liefertermin hinterlegen.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    W("t08-07", "HBOD bestellt die Ware schon, bevor die Artikel im System angelegt sind.", False,
      "Falsch. Erst wenn die Artikel angelegt sind, kann das Lager sie annehmen, scannen und einsortieren.", quelle="Gespräch mit Kollegen (Erfahrungswert), Deine Zusammenfassung", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t08-08", "Wie muss die Ware angeliefert werden?",
      ["Verpackt im Karton oder Polybag und mit EAN-Barcode", "Lose auf der Palette, ohne Barcode", "Nur in Geschenkpapier", "Egal, HBOD packt alles kostenlos um"],
      "Fehlt die Verpackung oder der Barcode, kostet das extra: Polybag 0,54 €, EAN-Sticker 1,05 € je Artikel.", quelle="Deine Zusammenfassung, Preisliste 10/2026"),
    S("t08-09", "Wer liefert die Modelfotos?",
      ["Die Marke. HBOD kann auf Wunsch Packshots gegen Aufpreis erstellen.", "HBOD fotografiert alles kostenlos", "Der Marktplatz", "Der Endkunde"],
      "Fotos müssen den Vorgaben der Marktplätze entsprechen. Das Grafikteam prüft vorab und meldet fehlende Bilder.", quelle="Deine Zusammenfassung"),
    S("t08-10", "Was ist bei Saisonware besonders wichtig?",
      ["Früh planen: Stammdaten und Liefertermin rechtzeitig hinterlegen, sonst ist die Saison vorbei", "Saisonware erst nach der Saison schicken", "Saisonware nie auf Zalando listen", "Saisonware nur im Dezember verkaufen"],
      "Früherer Schmerzpunkt einer Marke: Der Livegang kam so spät, dass die Hauptsaison schon vorbei war.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    M("t08-11", "Was braucht HBOD von einer Marke für eine erste Beispielrechnung? Kreuze alles Richtige an.",
      ["UVP oder aktuellen Verkaufspreis", "Mindestauszahlung oder EK", "SKUs bzw. Größen", "Artikelname oder Produktgruppe"],
      ["Passwort des Onlineshops", "Gehaltsliste der Mitarbeiter"],
      "Am besten für das ganze Sortiment, nicht nur für Beispiele. Dazu eine Referenz zur Retourenquote.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t08-12", "Was braucht HBOD für Markenfreigaben, falls keine vorhanden sind?",
      ["Logo, durchschnittlichen Verkaufspreis, Website und Instagram", "Nur die Steuernummer", "Den Handelsregisterauszug von HBOD", "Eine Liste der Wettbewerber"],
      "Das sagte HBOD im Neukundengespräch. Das Formular Brand Info fragt Name, Website, Instagram, Kategorie, Zielgruppe, Durchschnittspreis und SKU-Anzahl pro Jahr ab. Das Logo kommt zusätzlich dazu.", quelle="Gespräch mit Kollegen (Erfahrungswert), Brand Info", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
],
    punkte=["Unterlagen für Neukunden: Anlieferbedingungen, Stammdatenblatt, Vorgaben für Produktfotos, Preisliste, GPSR-Formular und Brand Info. Eine Onboarding-Gebühr gibt es nicht.", "HBOD bestellt erst, wenn die Artikel angelegt sind. Sonst kann das Lager die Ware nicht annehmen und scannen.", "Initialorder mindestens 3 Stück je SKU, geplant für etwa 8 Wochen Absatz, danach rollierend 4 bis 6 Wochen Reichweite.", "Live meist 1 bis 4 Wochen nach vollständigen Stammdaten. Häufigste Verzögerung: fehlende oder späte Daten und Bilder. Saisonware früh planen.", "Anlieferung im Karton oder Polybag mit EAN-Barcode, sonst kosten Polybag (0,54 €) und EAN-Sticker (1,05 €) extra. Modelfotos liefert die Marke."],
    merksatz="Erst die Daten, dann die Ware.",
    quelle="Deine Zusammenfassung, Unternehmenspräsentation 2026, Preisliste 10/2026")

stapel("t09", "B", "Lager, Versand und Logistik",
    "Wie das Lager arbeitet und wie die Logistik abgerechnet wird.", [
    S("t09-01", "Wie wird der Wareneingang abgerechnet?",
      ["Pro Artikel (je Barcode-Scan) mit 0,15 €, nicht pro Karton", "Pro Palette mit 50 €", "Pauschal pro Monat", "Gar nicht, der Wareneingang ist kostenlos"],
      "Typische Kundenfrage: \"20 gleiche Artikel im Karton, nehmt ihr dann 20-mal 15 Cent?\" Antwort: Ja.", quelle="Einweisung Produktkalkulation"),
    S("t09-02", "Warum gilt der gleiche Preis auch für sortenrein gepackte Kartons?",
      ["Es ist ein Durchschnittspreis: Gemischte Kartons dauern länger, sortenreine gehen schneller", "Weil sortenreine Kartons verboten sind", "Weil HBOD daran besonders gut verdient", "Weil der Marktplatz das vorschreibt"],
      "Man nennt das Quersubventionierung. Ein Durchschnittspreis ist einfacher und fair für alle.", quelle="Einweisung Produktkalkulation"),
    S("t09-03", "Wonach wird die Lagergebühr berechnet?",
      ["Nach dem Volumen in m³ aus den gemeldeten Verpackungsmaßen: 29,95 € pro m³ und Monat", "Nach dem Gewicht in kg", "Nach dem Verkaufspreis", "Pauschal 10 € pro Artikel"],
      "Deshalb sind korrekte Maße in den Stammdaten wichtig.", quelle="Preisliste 10/2026"),
    Z("t09-04", "Ein Artikel ist verpackt 30 × 20 × 5 cm groß und liegt 2 Monate im Lager. Wie hoch sind die Lagerkosten für diesen Artikel?", 0.18,
      "Volumen: 0,30 m × 0,20 m × 0,05 m = 0,003 m³. Kosten: 0,003 × 29,95 € × 2 Monate = 0,18 €.", einheit="€", dez=2, quelle="Preisliste 10/2026"),
    S("t09-05", "Wann fällt die Langzeitlagergebühr an?",
      ["Wenn ein Artikel 9 Monate nicht nachbestellt wurde: dann 59,95 € pro m³", "Nach 4 Wochen", "Immer im Dezember", "Nur bei Retouren"],
      "Ladenhüter kosten also doppelt. Deshalb Abverkauf planen oder Ware zurückholen.", quelle="Preisliste 10/2026, Einweisung Produktkalkulation"),
    Z("t09-06", "Was kostet der DHL-Versand innerhalb Deutschlands für ein Paket unter 1 kg?", 3.69,
      "Die meisten Pakete wiegen unter 1 kg. HBOD hat über das Volumen gute DHL-Konditionen.", einheit="€", dez=2, quelle="Preisliste 10/2026"),
    S("t09-07", "Warum wiegen fast alle HBOD-Pakete unter 1 kg?",
      ["Weil HBOD vor allem kompakte Ware wie Wäsche und Mode verkauft", "Weil DHL schwerere Pakete nicht annimmt", "Weil die Marktplätze das vorschreiben", "Weil HBOD nur Socken verkauft"],
      "Leichte, kompakte Ware hält Versand- und Lagerkosten niedrig.", quelle="Preisliste 10/2026, Unternehmenspräsentation 2026"),
    S("t09-08", "Was passiert in der Peak Season mit dem Wareneingang?",
      ["Die Bearbeitung kann von etwa 7 auf 14 Tage steigen, deshalb früh liefern", "Er wird geschlossen", "Er wird kostenlos", "Er geht schneller, weil mehr Leute da sind"],
      "Vor Black Friday erhöht HBOD Forecast und Bestellung. Je früher die Planung steht, desto besser.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t09-11", "Was passiert, wenn die Paketdienste Peak-Zuschläge oder Preiserhöhungen verlangen?",
      ["HBOD gibt sie weiter und informiert schriftlich", "HBOD zahlt sie immer selbst", "Der Endkunde zahlt sie an der Haustür", "Sie werden ignoriert"],
      "Das steht unten in der Preisliste.", quelle="Preisliste 10/2026"),
    S("t09-12", "Ein Interessent hatte schlechte Erfahrungen mit einem „lieblosen“ Pick-&-Pack-Dienstleister. Was ist die richtige Reaktion?",
      ["Erst fragen, was genau er sich bei der Verpackung vorstellt, und prüfen, ob das mit den Marktplatz-SLAs vereinbar ist", "Sofort jede Sonderverpackung kostenlos zusagen", "Sagen, dass Verpackung egal ist", "Das Thema ignorieren"],
      "Erst Anforderungen klären, dann Leistung anbieten. Sonderwünsche müssen zu den Lieferzeiten der Marktplätze passen.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
],
    punkte=["Wareneingang 0,15 € je Artikel (je Scan). Lager 29,95 € je m³ und Monat nach den gemeldeten Maßen.", "Langzeitlager: Wird ein Artikel 9 Monate nicht nachbestellt, kostet der m³ 59,95 €. Ladenhüter kosten doppelt.", "DHL Deutschland unter 1 kg: 3,69 €. Fast alle Pakete wiegen unter 1 kg, weil HBOD vor allem kompakte Ware verkauft.", "In der Peak Season kann der Wareneingang von etwa 7 auf 14 Tage steigen, deshalb früh liefern.", "Preiserhöhungen und Peak-Zuschläge der Paketdienste gibt HBOD schriftlich weiter."],
    merksatz="Richtige Maße in den Stammdaten sparen Lagerkosten.",
    quelle="Preisliste 10/2026, Einweisung Produktkalkulation")

stapel("t10", "B", "Marketing und Verkaufshebel",
    "Sale-Events, Kampagnen, Kennzahlen wie ROAS und CTR, Black Friday.", [
    P("t10-01", "Ordne jedem Begriff die richtige Erklärung zu.",
      [["Sale-Event", "Der Marktplatz startet eine Aktion, HBOD reicht EANs mit Rabatt ein"], ["Preisreduktion", "HBOD senkt den Preis selbst, in Absprache mit der Marke"], ["SPA (Sponsored Product Ads)", "Ein Artikel wird gesponsert, bezahlt wird pro Klick"], ["SDA (Sponsored Display Ads)", "Ein Banner für die Marke, vor allem für Aufmerksamkeit"]],
      "Kampagne und Sale-Event sind nicht dasselbe. Auf Amazon heißen die Formate Sponsored Products, Sponsored Brands (Marken-Banner in der Suche) und Sponsored Display (Bildanzeigen, auch außerhalb von Amazon).", quelle="Deine Zusammenfassung, Amazon Ads"),
    S("t10-02", "Welcher Artikel wird bei Sponsored Product Ads beworben?",
      ["Immer der Vaterartikel", "Immer die kleinste Größe", "Der teuerste Kindartikel", "Ein zufälliger Artikel"],
      "Der Vaterartikel bündelt alle Farben und Größen. Der Kunde wählt dann seine Variante.", quelle="Deine Zusammenfassung"),
    S("t10-03", "Wer entscheidet über die Teilnahme an Aktionen wie Black Friday?",
      ["Die Marke. HBOD gibt Impulse und Vorschläge, umgesetzt wird nur in Abstimmung.", "Nur HBOD", "Nur der Marktplatz", "Der Endkunde"],
      "Das ist ein wichtiges Vertrauensargument: Ohne Zustimmung der Marke wird nichts rabattiert.", quelle="Deine Zusammenfassung"),
    Z("t10-04", "Eine Kampagne kostet 2.000 € und bringt 11.000 € Umsatz. Wie hoch ist der ROAS?", 5.5,
      "ROAS = Umsatz ÷ Werbeausgaben = 11.000 ÷ 2.000 = 5,5. Für 1 € Werbung kommen 5,50 € Umsatz.", einheit="", dez=1, quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    Z("t10-05", "Eine Anzeige wird 20.000-mal angezeigt und 300-mal angeklickt. Wie hoch ist die CTR in Prozent?", 1.5,
      "CTR = Klicks ÷ Impressionen × 100 = 300 ÷ 20.000 × 100 = 1,5 %.", einheit="%", dez=1, quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    Z("t10-06", "Nach allen Kosten bleiben vor Werbung 25 % vom Umsatz übrig. Ab welchem ROAS lohnt sich Werbung gerade so (Break-even)?", 4.0,
      "Break-even-ROAS = 1 ÷ Marge = 1 ÷ 0,25 = 4. Darunter kostet die Werbung mehr, als sie bringt.", einheit="", dez=1, quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    S("t10-07", "Was sagt ein hoher ROAS nicht aus?",
      ["Ob die Werbung wirklich Gewinn bringt, denn Retouren und Kosten sind nicht abgezogen", "Wie viel Umsatz pro Werbe-Euro entsteht", "Wie effizient die Kampagne Umsatz erzeugt", "Dass überhaupt Werbung geschaltet wurde"],
      "Gerade auf Zalando mit 20 bis 30 % Retouren sieht ein ROAS auf Bruttoumsatz besser aus, als er ist.", quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    S("t10-08", "Wie stark ist der November im Vergleich zum restlichen Jahr?",
      ["Der November allein ist etwa so stark wie ein ganzes Quartal", "Der November ist der schwächste Monat", "Der November ist wie jeder andere Monat", "Im November wird nichts verkauft"],
      "Gründe: Weihnachtsgeld, Geschenke, viele Angebote. Gute Rankings wirken bis in Januar und Februar.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    P("t10-09", "Ordne die Mindestrabatte für Black Friday / Cyber Week zu (Stand der Gespräche 2026).",
      [["Zalando (Cyber Monday)", "mindestens 10 % (vorher 20 %)"], ["OTTO", "meist 20 %"], ["Amazon", "kein Mindestrabatt"]],
      "Laut Aufnahme gilt der Mindestrabatt von 10 % bei Zalando für den Cyber Monday. Die Marke muss nicht das ganze Sortiment einreichen, z. B. nur Überbestände oder Top-Performer.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Aus einer Gesprächsaufnahme. Die Werte ändern sich jedes Jahr, für das aktuelle Jahr beim Marketing bestätigen."),
    S("t10-10", "Warum sollte die Marke früh über ihre Black-Friday-Teilnahme entscheiden?",
      ["Wegen der Einreichungsfristen der Marktplätze und weil HBOD vorher Forecast und Bestellung erhöht", "Weil Black Friday sonst ausfällt", "Weil HBOD sonst die Provision erhöht", "Das ist egal, man kann am Tag selbst entscheiden"],
      "Fristen und Mindestrabatte gibt HBOD der Marke vor. In der Peak Season kann der Wareneingang von etwa 7 auf 14 Tage steigen, deshalb muss die Ware früh kommen.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    M("t10-11", "Welche Hebel hat HBOD, um den Abverkauf anzuregen? Kreuze alles Richtige an.",
      ["Teilnahme an Sale-Events", "Preisreduktionen", "Bundles und Multipacks", "Werbekampagnen"],
      ["Weniger Bestand einlagern, damit Artikel knapp wirken", "Bewertungen selbst schreiben"],
      "Bewertungen selbst zu schreiben wäre unzulässig. Knappheit durch wenig Bestand führt nur zu Lost Sales.", quelle="Deine Zusammenfassung"),
    S("t10-12", "Ein Kunde fragt, wie viel Werbebudget sinnvoll ist. Welcher Richtwert fiel in deinen Gesprächen?",
      ["Viele Kunden nehmen etwa 5 % vom Umsatz als Marketingbudget", "Mindestens 50 % vom Umsatz", "Werbung ist immer kostenlos", "Genau 1.000 € pro Monat"],
      "Das Budget bringt der Kunde. HBOD übernimmt Aufschalten, Beobachten, Optimieren und Reporten.", quelle="Deine Notizen", hinweis="Richtwert aus Gespräch, vor Nennung intern bestätigen"),
    S("t10-13", "Warum verkaufen sich exklusive Artikel oft besser als Basics?",
      ["Weil es weniger Preiskonkurrenz durch andere Händler gibt", "Weil Basics verboten sind", "Weil exklusive Artikel immer billiger sind", "Weil Marktplätze Basics verstecken"],
      "Die Top-Seller der Marke sind bei HBOD nicht immer die Top-Seller. Deshalb erst breit starten und auswerten.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
],
    punkte=["Marketing heißt bei HBOD: Aktionen, Preise und Werbung auf den Marktplätzen, keine Plakate oder TV-Spots.", "Sale-Event: Der Marktplatz startet eine Aktion, HBOD reicht EANs mit Rabatt ein. Preisreduktion: HBOD senkt den Preis selbst, in Absprache mit der Marke.", "Sponsored Product Ads bewerben immer den Vaterartikel, bezahlt wird pro Klick. Sponsored Display Ads sind Banner, vor allem für Aufmerksamkeit.", "Über Aktionen wie Black Friday entscheidet die Marke. HBOD gibt Impulse und nennt Fristen und Mindestrabatte.", "ROAS = Umsatz ÷ Werbeausgaben. Break-even-ROAS = 1 ÷ Marge vor Werbung. Ein hoher ROAS sagt nichts über Gewinn, besonders bei vielen Retouren."],
    merksatz="Die Marke entscheidet, HBOD macht Vorschläge und setzt um.",
    quelle="Deine Zusammenfassung, Amazon Ads, Gespräch mit Kollegen (Erfahrungswert)",
    hinweis="Mindestrabatte und Werbebudget sind Erfahrungswerte aus Gesprächen. Vor Nennung beim Marketing bestätigen.")

stapel("t11", "B", "Zalando im Detail",
    "Fair Pricing, Season Cleaning, Size Availability, Provisionen und Freigaben.", [
    S("t11-01", "Was ist der Grundgedanke von Zalandos Fair Pricing?",
      ["Der Zalando-Preis darf nicht deutlich über dem Preis liegen, den die Marke selbst verlangt, z. B. im eigenen Shop inklusive Versand", "Zalando bestimmt den Preis aller Artikel selbst", "Alle Artikel kosten auf Zalando gleich viel", "Zalando zahlt der Marke einen fairen Festpreis"],
      "Laut den Gesprächen liegt die Grenze bei etwa 15 %. Wird sie verletzt, sperrt Zalando den Artikel. Auch Auslandspreise werden verglichen.", quelle="Gespräch mit Kollegen (Erfahrungswert), Deine Zusammenfassung", hinweis="In den Unterlagen ist die Richtung der 15-%-Regel unterschiedlich formuliert. Genaue Regel intern bestätigen."),
    S("t11-02", "Was ist Season Cleaning?",
      ["Zalando bewertet jeden Monat die Performance der letzten 12 Monate und blockiert schwache Artikel", "Die Reinigung des Lagers", "Ein Rabatt-Event im Sommer", "Das Löschen aller Bilder nach einer Saison"],
      "HBOD informiert proaktiv mit Excel-Listen und Handlungsempfehlungen.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    M("t11-03", "Ein Artikel wurde im Season Cleaning geblockt. Welche Möglichkeiten gibt es? Kreuze alles Richtige an.",
      ["Mit etwa 10 % Rabatt online lassen", "Doppellisting unter neuer EAN", "Retagging für 2 bis 3 weitere Saisons"],
      ["Einfach den Preis erhöhen", "Den Artikel bei einem anderen Händler kaufen"],
      "Retagging heißt, den Artikel einer neuen Saison zuzuordnen.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Aus einer Gesprächsaufnahme. Intern bestätigen."),
    Z("t11-04", "Unter welchem Wert der Size Availability (in %) wird es bei Zalando kritisch?", 80.0,
      "Size Availability = Anteil der Größen, die lieferbar sind. Laut Gespräch wird ein Artikel unter etwa 80 % als Saisonware eingestuft und nach Ablauf der Saison blockiert.", einheit="%", dez=0, quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Aus einer Gesprächsaufnahme. Intern bestätigen."),
    S("t11-05", "Was folgt daraus für die Bestandsplanung?",
      ["Alle gängigen Größen müssen verfügbar sein, nicht nur einzelne", "Man sollte nur eine Größe pro Artikel anbieten", "Größen spielen auf Zalando keine Rolle", "Man sollte möglichst wenig Bestand haben"],
      "Fehlen Größen, verliert der Artikel Sichtbarkeit. Das kostet Umsatz.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t11-06", "Welches Land ist laut den Gesprächen der zweitgrößte Zalando-Markt?",
      ["Schweiz", "Polen", "Spanien", "Finnland"],
      "In der Schweiz sind höhere Preise möglich, die Logistik ist aber teurer. Öffentlich belegt ist, dass Zalando seit Jahren der umsatzstärkste Onlineshop der Schweiz ist.", quelle="Gespräch mit Kollegen (Erfahrungswert), Handelsverband Schweiz", hinweis="Aussage aus einer Gesprächsaufnahme. Intern bestätigen."),
    M("t11-07", "Was zählt bei der Zalando-Markenfreigabe? Kreuze alles Richtige an.",
      ["Anzahl der SKUs", "Durchschnittliche Verkaufspreise", "Produktkategorie", "Social-Media-Präsenz"],
      ["Mitarbeiterzahl der Marke", "Firmensitz in Berlin"],
      "Zalando ist stark kuratiert. Es gab zwischenzeitlich sogar einen Aufnahmestopp für neue Marken.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t11-08", "Wer hilft HBOD bei Zalando-Problemen, die über das Ticketsystem nicht lösbar sind?",
      ["Die Zalando-Partnermanagerin bzw. der Partner Manager", "Der Endkunde", "DHL", "Niemand"],
      "Über den Partner Manager kann HBOD auch eine Markenfreigabe anfragen. Erfolg zusagen kann man aber nicht.", quelle="Einarbeitung"),
    S("t11-09", "Eine Marke will wissen, welche ihrer Artikel bei Zalando geblockt sind. Was kann HBOD tun?",
      ["Auf Anfrage einen Datenexport aus Zalando ziehen und mit Handlungsempfehlung schicken", "Einen Live-Zugang zum Blockstatus geben", "Nichts, das ist geheim", "Alle Artikel neu anlegen"],
      "Ein Live-Tool für Blockaden gibt es nicht. Das sollte man ehrlich sagen.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t11-11", "Wie sind die Zalando-Provisionen aufgebaut?",
      ["Gestaffelt nach Geschlecht, Kategorie und Preis, mit einer Basis von 7,18 %", "Pauschal 15 % auf alles", "Immer 1 € pro Artikel", "Zalando nimmt keine Provision"],
      "Beispiel Damen-Textil bis 49,99 €: 7,18 %. Herren 50 bis 99,99 €: 20,18 %.", quelle="Einweisung Produktkalkulation (Blatt Commission Fees)"),
    Z("t11-12", "Welche Provision (in %) verlangt Zalando für Herren-Textil zwischen 30 und 49,99 €?", 16.18,
      "Laut Excel-Blatt Commission Fees: 16,18 %. Herrenartikel werden weniger retourniert, deshalb nehmen Marktplätze dort mehr.", einheit="%", dez=2, quelle="Einweisung Produktkalkulation"),
],
    punkte=["Zalando funktioniert wie ein Katalog zum Stöbern. Kunden bestellen oft zur Auswahl, die Retoure ist kostenlos. Retourenquote laut Gesprächen etwa 20 bis 30 %.", "Zalando ist stark kuratiert. Für die Freigabe zählen SKU-Anzahl, Durchschnittspreise, Kategorie und Social-Media-Präsenz.", "Fair Pricing: Der Zalando-Preis darf nicht deutlich über dem eigenen Preis der Marke liegen (laut Gesprächen etwa 15 %), sonst sperrt Zalando den Artikel.", "Season Cleaning blockiert schwache Artikel. Möglich sind dann etwa 10 % Rabatt, ein Doppellisting unter neuer EAN oder Retagging. Size Availability unter etwa 80 % ist kritisch.", "Provision gestaffelt nach Geschlecht, Kategorie und Preis, Basis 7,18 %. Herren-Textil 30 bis 49,99 €: 16,18 %."],
    merksatz="Viel Reichweite für Mode, aber durch Retouren oft weniger Auszahlung als bei Amazon.",
    quelle="Gespräch mit Kollegen (Erfahrungswert), Einweisung Produktkalkulation, Einarbeitung",
    hinweis="Fair Pricing, Season Cleaning und Size Availability stammen aus Gesprächen. Intern bestätigen.")

stapel("t12", "B", "Amazon, ABOUT YOU, OTTO und Co.",
    "Provisionen, Kennzahlen und Besonderheiten der anderen großen Marktplätze.", [
    S("t12-01", "Wie hoch ist die Amazon-Provision in der HBOD-Excel?",
      ["Pauschal 15 % vom Bruttopreis, unabhängig von Kategorie und Preis", "Gestaffelt von 5 bis 30 %", "1 € pro Artikel", "Amazon nimmt keine Provision"],
      "Für Amazon muss man in der Excel deshalb keine Kategorie wählen.", quelle="Einweisung Produktkalkulation"),
    Z("t12-02", "Wie hoch ist die ABOUT-YOU-Provision für Herren-Textil zwischen 25 und 50 € (in %)?", 21.0,
      "Laut Commission Fees: Herren unter 25 € 10 %, 25 bis 50 € 21 %. Bei Damen ist es in dieser Stufe 11 %.", einheit="%", dez=0, quelle="Einweisung Produktkalkulation"),
    S("t12-03", "Warum nehmen Marktplätze bei Herrenartikeln teils höhere Provisionen als bei Damenartikeln?",
      ["Herrenartikel werden weniger retourniert, der Marktplatz verliert dadurch weniger", "Herren zahlen lieber", "Das ist reine Willkür", "Weil Herrenartikel schwerer sind"],
      "Es ist eine Staffelprovision mit einer Logik dahinter, keine Beliebigkeit.", quelle="Einweisung Produktkalkulation"),
    P("t12-04", "Ordne die Basisprovisionen zu (laut Excel).",
      [["bol", "5,7 %"], ["Kaufland", "14 %"], ["Amazon", "15 %"], ["OTTO", "16,5 %"]],
      "Die Provisionen gibt HBOD 1:1 an die Marke weiter.", quelle="Einweisung Produktkalkulation"),
    S("t12-05", "Was bedeutet es, wenn ein Verkäufer bei Amazon den Prime-Status verliert?",
      ["Die Artikel werden weiter verkauft, aber ohne Prime-Hinweis, und das kostet Umsatz", "Die Artikel werden gelöscht", "HBOD darf nicht mehr auf Amazon verkaufen", "Die Marke muss Strafe zahlen"],
      "Prime verspricht schnelle Lieferung. Werden Pakete zu spät zugestellt, ist Prime weg.", quelle="Einarbeitung"),
    P("t12-06", "Ordne die Amazon-Kennzahlen ihren üblichen Zielwerten zu.",
      [["Auftragsmängelquote (Order Defect Rate)", "unter 1 %"], ["Stornoquote vor Versand", "unter 2,5 %"], ["Quote verspäteter Lieferungen", "unter 4 %"], ["Quote gültiger Sendungsnummern", "über 95 %"]],
      "Diese Werte gehören zur Account Health. Werden sie gerissen, drohen Warnungen bis zur Sperre.", quelle="Allgemeinwissen Amazon Seller Central", hinweis="Amazon kann Werte ändern"),
    S("t12-09", "Die Monatsabrechnung kommt zu spät, weil ein Marktplatz seine Abrechnung noch nicht geliefert hat. Was tust du?",
      ["Den Kunden proaktiv informieren, warum es später wird", "Abwarten und nichts sagen", "Die Abrechnung schätzen", "Dem Kunden sagen, er soll ABOUT YOU anrufen"],
      "Verzögerungen proaktiv kommunizieren schafft Vertrauen.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t12-11", "Ein Kunde ist schon selbst auf ABOUT YOU, aber nur in Deutschland. Was ist eine gute Frage an ihn?",
      ["\"Bietet ihr nur in Deutschland an oder auch auf den internationalen ABOUT-YOU-Marktplätzen?\"", "\"Warum seid ihr nicht auf Amazon?\"", "\"Wie heißt euer Steuerberater?\"", "\"Wollt ihr ABOUT YOU kündigen?\""],
      "Viele Marken verkaufen auf einem Marktplatz nur im Heimatland. Die internationalen Länder desselben Marktplatzes sind oft ein schneller Zusatznutzen.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t12-12", "Bei welchem Marktplatz ist das Retourenlabel nicht automatisch im Paket, sodass der Kunde es selbst erzeugen muss?",
      ["Amazon", "Zalando", "ABOUT YOU", "bei allen gleich"],
      "Diese kleine Hürde ist ein Grund für die niedrigere Retourenquote bei Amazon.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
],
    punkte=["Amazon funktioniert wie eine Suchmaschine. Die Retourenquote ist niedrig, auch weil der Kunde das Retourenlabel selbst erzeugen muss.", "Provision laut HBOD-Kalkulation: Amazon pauschal 15 % vom Bruttopreis, bol 5,7 %, Kaufland 14 %, OTTO 16,5 %. Zalando und ABOUT YOU staffeln nach Geschlecht, Kategorie und Preis.", "Herrenartikel kosten oft mehr Provision, weil sie seltener retourniert werden.", "Prime verlangt pünktliche Lieferung. Amazon-Zielwerte: Auftragsmängelquote unter 1 %, Stornoquote unter 2,5 %, verspätete Lieferungen unter 4 %.", "Die Marktplatzprovisionen gibt HBOD 1:1 an die Marke weiter."],
    merksatz="Bei gleichem Preis zahlt Amazon oft deutlich mehr aus als Zalando, weil weniger zurückkommt.",
    quelle="Einweisung Produktkalkulation, Allgemeinwissen Amazon Seller Central, Unternehmenspräsentation 2026",
    hinweis="Amazon kann die Zielwerte ändern.")
